CREATE TABLE accounts(id TEXT PRIMARY KEY, label TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE namespaces(slug TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE grants(account_id TEXT NOT NULL REFERENCES accounts(id), kind TEXT NOT NULL, target TEXT NOT NULL, PRIMARY KEY(account_id,kind,target));
CREATE TABLE tokens(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), digest TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, label TEXT NOT NULL, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE packages(ref TEXT PRIMARY KEY, quota_owner TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE owners(ref TEXT NOT NULL REFERENCES packages(ref), account_id TEXT NOT NULL REFERENCES accounts(id), role TEXT NOT NULL CHECK(role IN ('owner','publisher')), PRIMARY KEY(ref,account_id));
CREATE TABLE releases(ref TEXT NOT NULL REFERENCES packages(ref), version TEXT NOT NULL, sort_key TEXT NOT NULL, common_json TEXT NOT NULL, common_hash TEXT NOT NULL, yanked INTEGER NOT NULL DEFAULT 0, yank_reason TEXT, quarantined INTEGER NOT NULL DEFAULT 0, published_at INTEGER NOT NULL, PRIMARY KEY(ref,version));
CREATE INDEX release_order ON releases(ref,sort_key DESC);
CREATE TABLE artifacts(ref TEXT NOT NULL, version TEXT NOT NULL, variant TEXT NOT NULL, digest TEXT NOT NULL, size INTEGER NOT NULL, metadata TEXT NOT NULL, profile TEXT NOT NULL, quarantined INTEGER NOT NULL DEFAULT 0, published_at INTEGER NOT NULL, PRIMARY KEY(ref,version,variant), FOREIGN KEY(ref,version) REFERENCES releases(ref,version));
CREATE TABLE sessions(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), token_id TEXT NOT NULL REFERENCES tokens(id), ref TEXT NOT NULL, version TEXT NOT NULL, variant TEXT NOT NULL, digest TEXT NOT NULL, size INTEGER NOT NULL, profile TEXT NOT NULL, quota_owner TEXT NOT NULL, state TEXT NOT NULL, reserved INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, receiving_until INTEGER NOT NULL DEFAULT 0, upload_key TEXT, worker_fence TEXT, lease_until INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, reason_code TEXT, completed_at INTEGER);
CREATE UNIQUE INDEX variant_reservation ON sessions(ref,version,variant) WHERE reserved=1;
CREATE INDEX session_jobs ON sessions(state,lease_until);
CREATE TABLE traffic(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), profile TEXT NOT NULL, bytes INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX traffic_window ON traffic(account_id,profile,created_at);
CREATE TABLE idempotency(account_id TEXT NOT NULL, action TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL, status INTEGER NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(account_id,action,key));
CREATE TABLE audit(id TEXT PRIMARY KEY, kind TEXT NOT NULL, account_id TEXT, ref TEXT, version TEXT, variant TEXT, size INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE outbox(id TEXT PRIMARY KEY REFERENCES audit(id), delivered INTEGER NOT NULL DEFAULT 0);
CREATE TABLE catalog(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL);
INSERT INTO catalog VALUES(1,1);
CREATE TABLE rate_limits(bucket TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
